document.addEventListener("DOMContentLoaded",()=>{if("undefined"==typeof Chart)return;const a=getComputedStyle(document.documentElement),t=(t,e)=>a.getPropertyValue(t).trim()||e,e={gold:t("--gold-dark","#c2933f"),teal:t("--teal","#12433f"),navy:t("--navy","#0d2b30")};document.querySelectorAll(".admin-chart-canvas").forEach(a=>{let t=[],l=[],d=[];try{t=JSON.parse(a.dataset.chartLabels||"[]"),l=JSON.parse(a.dataset.chartValues||"[]"),d=JSON.parse(a.dataset.chartTooltips||"[]")}catch(a){return}const n=e[a.dataset.chartColor]||e.gold,o=a.dataset.chartUnit||"";new Chart(a,{type:"bar",data:{labels:t,datasets:[{data:l,backgroundColor:n,borderRadius:4,maxBarThickness:34}]},options:{responsive:!0,maintainAspectRatio:!1,plugins:{legend:{display:!1},tooltip:{rtl:!0,titleFont:{family:"Tajawal"},bodyFont:{family:"Tajawal"},callbacks:{title:a=>d[a[0].dataIndex]||t[a[0].dataIndex],label:a=>`${a.parsed.y}${o?" "+o:""}`}}},scales:{x:{grid:{display:!1},ticks:{font:{family:"Tajawal",size:11}}},y:{beginAtZero:!0,ticks:{precision:0,font:{family:"Tajawal",size:11}}}}}})})});